function damGeometry(){const v=[];stations.forEach(([x,b])=>{const yd=9.7+.83*(298-b);[[x,0,b],[x,0,306],[x,9.7,306],[x,9.7,298],[x,yd,b]].forEach(q=>{const p=P(q);v.push(p.x,p.y,p.z)})});const idx=[],n=stations.length,edges=[[0,1],[1,2],[2,3],[3,4],[4,0]];idx.push(0,2,1,0,3,2,0,4,3);let o=(n-1)*5;idx.push(o,o+1,o+2,o,o+2,o+3,o,o+3,o+4);for(let i=0;i<n-1;i++)edges.forEach(([a,b])=>idx.push(i*5+a,(i+1)*5+b,i*5+b,i*5+a,(i+1)*5+a,(i+1)*5+b));const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(v,3));g.setIndex(idx);g.computeVertexNormals();return g}
