function terrainMesh(side){const nx=18,nz=18,verts=[],idx=[];const xBase=side==='north'?-115.5:115.5;for(let i=0;i<nx;i++){for(let j=0;j<nz;j++){const dx=i/(nx-1)*105,dz=(j/(nz-1)-.42)*300;const x=xBase+(side==='north'?-dx:dx);const near=Math.abs(dx);const ridge=92+near*.55+22*Math.sin(j*.52)+9*Math.sin(i*.8+j*.35);const valley=32+Math.abs(dz)*.17;const y=Math.max(0,Math.min(150,ridge+valley-70*Math.exp(-(dz*dz)/7000)));verts.push(x,y,dz)}}for(let i=0;i<nx-1;i++)for(let j=0;j<nz-1;j++){const a=i*nz+j,b=a+nz,c=b+1,d=a+1;idx.push(a,b,d,b,c,d)}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(verts,3));g.setIndex(idx);g.computeVertexNormals();const m=new THREE.Mesh(g,material(side==='north'?C.terrain:C.rock,{roughness:1}));m.receiveShadow=true;m.name=side==='north'?'北岸山体':'南岸山体';return m}
