  groups.hydraulic=new THREE.Group();[115,129].forEach((x,i)=>box(groups.hydraulic,`溢流孔${i+1}`,x-3.45,x+3.45,-4.5,20,296,305,C.spill,.72));[101,143].forEach((x,i)=>{box(groups.hydraulic,`底孔${i+1}`,x-1.9,x+1.9,0,103.5,228,234,C.outlet,.9);box(groups.hydraulic,`出口平台${i+1}`,x-8.5,x+8.5,47,103.5,215,253,0xc47b4c,.43)});scene.add(groups.hydraulic);
