function updateDetector(){if(!scene)return;groups.cone.clear();const c=candidates[active],p=P([c.x,c.y,c.z]);detector=new THREE.Mesh(new THREE.BoxGeometry(1.6,.5,1.2),material(C.detector,{emissive:C.detector,emissiveIntensity:.55}));detector.position.copy(p);groups.cone.add(detector);const az=THREE.MathUtils.degToRad(c.az),el=THREE.MathUtils.degToRad(c.el),dir=new THREE.Vector3(-Math.cos(el)*Math.cos(az),Math.sin(el),-Math.cos(el)*Math.sin(az)).normalize(),length=95,r=Math.tan(THREE.MathUtils.degToRad(c.fov/2))*length;cone=new THREE.Mesh(new THREE.ConeGeometry(r,length,32,1,true),new THREE.MeshBasicMaterial({color:C.cone,transparent:true,opacity:.12,side:THREE.DoubleSide,depthWrite:false}));cone.position.copy(p.clone().add(dir.clone().multiplyScalar(length/2)));cone.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),dir);groups.cone.add(cone);const line=new THREE.ArrowHelper(dir,p,length,C.detector,5,2);groups.cone.add(line);metrics()}
