function renderList(){const h=$('#candidateList');h.innerHTML='';candidates.forEach((c,i)=>{const d=document.createElement('div');d.className='candidate'+(i===active?' active':'');d.innerHTML=`<b>${c.name}</b><span>x ${c.x.toFixed(1)} · y ${c.y.toFixed(1)} · ▽${c.z.toFixed(1)}</span>`;d.onclick=()=>{active=i;sync();renderList();updateDetector()};h.append(d)})}
function sync(){const c=candidates[active];['name','x','y','z','az','el','fov'].forEach(k=>$('#'+k).value=c[k]);$('#azOut').textContent=c.az+'°';$('#elOut').textContent=c.el+'°';$('#fovOut').textContent=c.fov+'°'}
function metrics(){const c=candidates[active],el=THREE.MathUtils.degToRad(c.el),base=c.y>40?34:c.z<220?82:50,path=Math.max(7,base/Math.max(.18,Math.cos(el))),opacity=path*2.4,terrainPenalty=c.x<25||c.x>205?.65:1,sky=Math.round(100*Math.max(.12,Math.sin(Math.max(.08,el)))*terrainPenalty),count=Math.round(7200*Math.exp(-opacity/100)*Math.max(.15,sky/100)),score=Math.round(Math.min(100,.36*sky+.36*Math.min(100,count/16)+.28*Math.min(100,c.fov/55*100)));$('#path').textContent=path.toFixed(0)+' m';$('#opacity').textContent=opacity.toFixed(0);$('#count').textContent=count>999?(count/1000).toFixed(1)+'k':count;$('#sky').textContent=sky+'%';$('#score').textContent=score;$('#ring').style.background=`conic-gradient(var(--cyan) 0 ${score}%,#19313c ${score}%)`;$('#grade').textContent=score>=72?'条件可行':score>=48?'需要优化':'风险较高'}
