['name','x','y','z','az','el','fov'].forEach(k=>$('#'+k).addEventListener('input',e=>{candidates[active][k]=k==='name'?e.target.value:+e.target.value;sync();renderList();updateDetector()}));$$('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));$$('[data-layer]').forEach(e=>e.onchange=()=>groups[e.dataset.layer].visible=e.checked);$('#upLevel').oninput=()=>updateWater('upwater');$('#downLevel').oninput=()=>updateWater('downwater');$('#add').onclick=()=>{candidates.push({...candidates[active],name:'新候选点 '+(candidates.length+1)});active=candidates.length-1;sync();renderList();updateDetector()};$('#duplicate').onclick=$('#add').onclick;$('#remove').onclick=()=>{if(candidates.length<2)return;candidates.splice(active,1);active=Math.max(0,active-1);sync();renderList();updateDetector()};$('#save').onclick=()=>{localStorage.setItem('muon-three-candidates',JSON.stringify(candidates));$('#saved').textContent='已保存到本机浏览器。'};$('#export').onclick=()=>{const a=document.createElement('a'),data={model:'周宁下库大坝 Three.js 方案模型',coordinates:'x坝轴向北/y下游/z高程',water:{upstream:+$('#upLevel').value,downstream:+$('#downLevel').value},candidates};a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download='周宁缪子探测器部署方案.json';a.click();URL.revokeObjectURL(a.href)};window.addEventListener('resize',resize);
try{const saved=JSON.parse(localStorage.getItem('muon-three-candidates'));if(Array.isArray(saved)&&saved.length)candidates.splice(0,candidates.length,...saved)}catch{}renderList();sync();
